 * https://github.com/JCTools/JCTools/blob/master/jctools-core/src/main/java/org/jctools/queues/atomic
 */

package io.reactivex.rxjava4.operators;

import static org.junit.Assert.*;

import java.util.concurrent.atomic.*;

import org.junit.Test;

import io.reactivex.rxjava4.core.RxJavaTest;
import io.reactivex.rxjava4.internal.queue.MpscLinkedQueue;

public class SimpleQueueTest extends RxJavaTest {

    @Test(expected = NullPointerException.class)
    public void spscArrayQueueNull() {
        SpscArrayQueue<Object> q = new SpscArrayQueue<>(16);
        q.offer(null);
    }

    @Test(expected = NullPointerException.class)
    public void spscLinkedArrayQueueNull() {
        SpscLinkedArrayQueue<Object> q = new SpscLinkedArrayQueue<>(16);
        q.offer(null);
    }

    @Test(expected = NullPointerException.class)
    public void mpscLinkedQueueNull() {
        MpscLinkedQueue<Object> q = new MpscLinkedQueue<>();
        q.offer(null);
    }

    @Test
    public void spscArrayQueueBiOffer() {
        SpscArrayQueue<Object> q = new SpscArrayQueue<>(16);
        q.offer(1, 2);

        assertEquals(1, q.poll());
        assertEquals(2, q.poll());
        assertNull(q.poll());
    }

    @Test
    public void spscLinkedArrayQueueBiOffer() {
        SpscLinkedArrayQueue<Object> q = new SpscLinkedArrayQueue<>(16);
        q.offer(1, 2);

        assertEquals(1, q.poll());
        assertEquals(2, q.poll());
        assertNull(q.poll());
    }

    @Test
    public void mpscLinkedQueueBiOffer() {
        MpscLinkedQueue<Object> q = new MpscLinkedQueue<>();
        q.offer(1, 2);

        assertEquals(1, q.poll());
        assertEquals(2, q.poll());
        assertNull(q.poll());
    }

    @Test
    public void spscBiOfferCapacity() {
        SpscArrayQueue<Integer> q = new SpscArrayQueue<>(8);
        assertTrue(q.offer(1, 2));
        assertTrue(q.offer(3, 4));
        assertTrue(q.offer(5, 6));
        assertTrue(q.offer(7));

        assertFalse(q.offer(8, 9));
        assertFalse(q.offer(9, 10));
    }

    @Test
    public void spscLinkedNewBufferPeek() {
        SpscLinkedArrayQueue<Integer> q = new SpscLinkedArrayQueue<>(8);
        assertTrue(q.offer(1, 2));
        assertTrue(q.offer(3, 4));
        assertTrue(q.offer(5, 6));
        assertTrue(q.offer(7, 8)); // this should trigger a new buffer

        for (int i = 0; i < 8; i++) {
            assertEquals(i + 1, q.peek().intValue());
            assertEquals(i + 1, q.poll().intValue());
        }

        assertNull(q.peek());
        assertNull(q.poll());
    }

    @Test
    public void mpscOfferPollRace() throws Exception {
        final MpscLinkedQueue<Integer> q = new MpscLinkedQueue<>();

        final AtomicInteger c = new AtomicInteger(3);

        Thread t1 = new Thread(new Runnable() {
            int i;
            @Override
            public void run() {
                c.decrementAndGet();
                while (c.get() != 0) { }

                while (i++ < 10000) {
                    q.offer(i);
                }
            }
        });
        t1.start();

        Thread t2 = new Thread(new Runnable() {
            int i = 10000;
            @Override
            public void run() {
                c.decrementAndGet();
                while (c.get() != 0) { }

                while (i++ < 10000) {
                    q.offer(i);
                }
            }
        });
        t2.start();

        Runnable r3 = new Runnable() {
            int i = 20000;
            @Override
            public void run() {
                c.decrementAndGet();
                while (c.get() != 0) { }

                while (--i > 0) {
                    q.poll();
                }
            }
        };

        r3.run();

        t1.join();
        t2.join();
    }

    @Test
    public void spscLinkedArrayQueueOfferTwoWrapAround() {
        // p2capacity=8, mask=7, buffer size=9 (indices 0-8, 8 is link slot)
        SpscLinkedArrayQueue<Integer> q = new SpscLinkedArrayQueue<>(8);

        // Fill 8 elements (producerIndex -> 8)
        for (int i = 0; i < 8; i++) {
            q.offer(i);
        }
        // Drain 8 elements (consumerIndex -> 8)
        for (int i = 0; i < 8; i++) {
            assertEquals(i, q.poll().intValue());
        }
        // producerIndex=8, consumerIndex=8, queue empty

        // Fill 7 elements so producerIndex=15 (15 & 7 = 7, which is mask)
        for (int i = 0; i < 7; i++) {
            q.offer(100 + i);
        }
        // Drain those 7 (consumerIndex -> 15)
        for (int i = 0; i < 7; i++) {
            assertEquals(100 + i, q.poll().intValue());
        }
        // producerIndex=15, consumerIndex=15, queue empty
        // Now p & mask == mask (15 & 7 == 7), so pi=7, pi+1=8=link slot

        // Call offer(first, second) - the buggy code writes second to buffer[8] (link slot)
        // instead of buffer[0] (correct wrapped position)
        q.offer(200, 201);

        // Both elements should be pollable in order
        assertEquals(200, q.poll().intValue());
        assertEquals(201, q.poll().intValue());
        assertNull(q.poll());
    }

    @Test
    public void spscLinkedArrayQueueNoNepotism() {
        SpscLinkedArrayQueue<Integer> q = new SpscLinkedArrayQueue<>(16);

        AtomicReferenceArray<Object> ara = q.producerBuffer;

        for (int i = 0; i < 20; i++) {
            q.offer(i);
        }

        assertNotNull(ara.get(16));

        for (int i = 0; i < 20; i++) {
            assertEquals(i, q.poll().intValue());
        }

        assertNull(ara.get(16));
    }
}

