package io.reactivex.rxjava4.internal.schedulers;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.Test;

import io.reactivex.rxjava4.core.Scheduler;
import io.reactivex.rxjava4.core.Scheduler.Worker;

/**
 * Regression test for race condition in SchedulerToExecutorService.shutdown().
 *
 * The first branch of shutdown() does:
 *   if (workerStore.get() instanceof Worker w) { w.dispose(); }
 * which reads the worker with get() but does not atomically replace it with SHUTDOWN.
 *
 * The else branch correctly uses getAndSet.
 *
 * This test demonstrates that when workerStore holds a Worker, a concurrently
 * set Worker is not disposed because get() does not atomically replace the value.
 */
public class SchedulerToExecutorServiceShutdownRaceTest {

    @Test
    public void shutdownDisposesWorkerSetConcurrently() throws InterruptedException {
        // Arrange: create a SchedulerToExecutorService with useWorker=true (non-null workerStore)
        Scheduler scheduler = mock(Scheduler.class);
        AtomicReference<Worker> workerStore = new AtomicReference<>();
        SchedulerToExecutorService executorService = new SchedulerToExecutorService(scheduler, workerStore);

        // Worker1: will be initially in the store
        Worker worker1 = mock(Worker.class);

        // Worker2: will be set concurrently during shutdown
        Worker worker2 = mock(Worker.class);

        // A latch to synchronize: worker1.dispose() signals that shutdown() has read
        // the worker but hasn't finished yet. We'll set worker2 in the window.
        CountDownLatch disposeCalledLatch = new CountDownLatch(1);
        CountDownLatch canProceedLatch = new CountDownLatch(1);

        // When worker1.dispose() is called, signal and then block waiting for permission
        doAnswer(invocation -> {
            disposeCalledLatch.countDown(); // signal we entered dispose
            canProceedLatch.await(5, TimeUnit.SECONDS); // block until test lets us proceed
            return null;
        }).when(worker1).dispose();

        // Set worker1 in the store
        workerStore.set(worker1);

        // Act: start shutdown() in a separate thread
        Thread shutdownThread = new Thread(executorService::shutdown);
        shutdownThread.start();

        // Wait for worker1.dispose() to start (this means shutdown() read worker1 via get())
        boolean gotSignal = disposeCalledLatch.await(5, TimeUnit.SECONDS);
        assertTrue("worker1.dispose() should have been called", gotSignal);

        // Now, during the window between get() and the end of dispose(), 
        // simulate another thread setting a new worker
        workerStore.set(worker2);

        // Let dispose() complete
        canProceedLatch.countDown();

        // Wait for shutdown thread to finish
        shutdownThread.join(5000);
        assertFalse("shutdown thread should have completed", shutdownThread.isAlive());

        // Assert: worker2 should have been disposed too
        // The correct behavior is that shutdown should use getAndSet to atomically
        // replace the worker, so it would capture worker2 and dispose it.
        // The bug is that it uses get() which doesn't atomically replace, so worker2
        // is missed.
        verify(worker2, times(1)).dispose();
    }
}

