package io.reactivex.rxjava4.internal.schedulers;

import static org.junit.Assert.*;

import java.util.concurrent.ConcurrentLinkedQueue;

import org.junit.Test;

import io.reactivex.rxjava4.core.RxJavaTest;
import io.reactivex.rxjava4.disposables.CompositeDisposable;
import io.reactivex.rxjava4.internal.schedulers.CachedScheduler.*;
import io.reactivex.rxjava4.testsupport.TestHelper;

public class CachedSchedulerInternalTest extends RxJavaTest {

    @Test
    public void expiredQueueEmpty() {
        ConcurrentLinkedQueue<ThreadWorker> expire = new ConcurrentLinkedQueue<>();
        CompositeDisposable cd = new CompositeDisposable();

        CachedWorkerPool.evictExpiredWorkers(expire, cd);
    }

    @Test
    public void expiredWorkerRemoved() {
        ConcurrentLinkedQueue<ThreadWorker> expire = new ConcurrentLinkedQueue<>();
        CompositeDisposable cd = new CompositeDisposable();

        ThreadWorker tw = new ThreadWorker(new RxThreadFactory("IoExpiryTest"));

        try {
            expire.add(tw);
            cd.add(tw);

            CachedWorkerPool.evictExpiredWorkers(expire, cd);

            assertTrue(tw.isDisposed());
            assertTrue(expire.isEmpty());
        } finally {
            tw.dispose();
        }
    }

    @Test
    public void noExpiredWorker() {
        ConcurrentLinkedQueue<ThreadWorker> expire = new ConcurrentLinkedQueue<>();
        CompositeDisposable cd = new CompositeDisposable();

        ThreadWorker tw = new ThreadWorker(new RxThreadFactory("IoExpiryTest"));
        tw.setExpirationTime(System.nanoTime() + 10_000_000_000L);

        try {
            expire.add(tw);
            cd.add(tw);

            CachedWorkerPool.evictExpiredWorkers(expire, cd);

            assertFalse(tw.isDisposed());
            assertFalse(expire.isEmpty());
        } finally {
            tw.dispose();
        }
    }

    @Test
    public void expireReuseRace() {
        ConcurrentLinkedQueue<ThreadWorker> expire = new ConcurrentLinkedQueue<>();
        CompositeDisposable cd = new CompositeDisposable();

        ThreadWorker tw = new ThreadWorker(new RxThreadFactory("IoExpiryTest"));
        tw.dispose();

        for (int i = 0; i < TestHelper.RACE_DEFAULT_LOOPS; i++) {
            expire.add(tw);
            cd.add(tw);

            TestHelper.race(
                    () -> CachedWorkerPool.evictExpiredWorkers(expire, cd),
                    () -> expire.remove(tw)
            );
        }
    }

    @Test
    public void expiredWorkerAfterNonExpiredShouldBeEvicted() {
        // ConcurrentLinkedQueue is FIFO, not ordered by expiration time.
        // The evictExpiredWorkers() method incorrectly breaks on the first
        // non-expired worker, skipping expired workers that come after it.
        ConcurrentLinkedQueue<ThreadWorker> expire = new ConcurrentLinkedQueue<>();
        CompositeDisposable cd = new CompositeDisposable();

        ThreadWorker twNonExpired = new ThreadWorker(new RxThreadFactory("IoExpiryTestNonExpired"));
        ThreadWorker twExpired = new ThreadWorker(new RxThreadFactory("IoExpiryTestExpired"));

        try {
            // Set twNonExpired to far future, so it's NOT expired.
            twNonExpired.setExpirationTime(System.nanoTime() + 10_000_000_000L);
            // Set twExpired to 0 (past), so it IS expired.
            twExpired.setExpirationTime(0L);

            // Add to queue in FIFO order: non-expired first, then expired.
            // The queue order is: [twNonExpired, twExpired]
            expire.add(twNonExpired);
            expire.add(twExpired);
            cd.add(twNonExpired);
            cd.add(twExpired);

            CachedWorkerPool.evictExpiredWorkers(expire, cd);

            // twNonExpired should NOT be disposed (not expired).
            assertFalse("Non-expired worker should not be disposed", twNonExpired.isDisposed());
            assertFalse("Non-expired worker should still be in queue", !expire.contains(twNonExpired));

            // twExpired SHOULD be disposed and removed from queue.
            // BUG: the code breaks on twNonExpired and never reaches twExpired.
            assertTrue("Expired worker (after non-expired) should be disposed", twExpired.isDisposed());
            assertFalse("Expired worker should be removed from queue", expire.contains(twExpired));
        } finally {
            twNonExpired.dispose();
            twExpired.dispose();
        }
    }
}

