    @Test
    public void multiplyCapZeroDoesNotDivideByZero() {
        assertEquals(0L, BackpressureHelper.multiplyCap(0, Long.MAX_VALUE));
        assertEquals(0L, BackpressureHelper.multiplyCap(Long.MAX_VALUE, 0));
        assertEquals(0L, BackpressureHelper.multiplyCap(0, 0));
    }
