package io.reactivex.rxjava4.internal.schedulers;

import static org.junit.Assert.*;

import java.util.concurrent.ConcurrentLinkedQueue;

import org.junit.Test;

import io.reactivex.rxjava4.core.RxJavaTest;
import io.reactivex.rxjava4.disposables.CompositeDisposable;
import io.reactivex.rxjava4.internal.schedulers.CachedScheduler.*;
import io.reactivex.rxjava4.testsupport.TestHelper;

import java.lang.reflect.Modifier;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicBoolean;

public class CachedSchedulerInternalTest extends RxJavaTest {

    @Test
    public void expiredQueueEmpty() {
        ConcurrentLinkedQueue<ThreadWorker> expire = new ConcurrentLinkedQueue<>();
        CompositeDisposable cd = new CompositeDisposable();

        CachedWorkerPool.evictExpiredWorkers(expire, cd);
    }

    @Test
    public void expiredWorkerRemoved() {
        ConcurrentLinkedQueue<ThreadWorker> expire = new ConcurrentLinkedQueue<>();
        CompositeDisposable cd = new CompositeDisposable();

        ThreadWorker tw = new ThreadWorker(new RxThreadFactory("IoExpiryTest"));

        try {
            expire.add(tw);
            cd.add(tw);

            CachedWorkerPool.evictExpiredWorkers(expire, cd);

            assertTrue(tw.isDisposed());
            assertTrue(expire.isEmpty());
        } finally {
            tw.dispose();
        }
    }

    @Test
    public void noExpiredWorker() {
        ConcurrentLinkedQueue<ThreadWorker> expire = new ConcurrentLinkedQueue<>();
        CompositeDisposable cd = new CompositeDisposable();

        ThreadWorker tw = new ThreadWorker(new RxThreadFactory("IoExpiryTest"));
        tw.setExpirationTime(System.nanoTime() + 10_000_000_000L);

        try {
            expire.add(tw);
            cd.add(tw);

            CachedWorkerPool.evictExpiredWorkers(expire, cd);

            assertFalse(tw.isDisposed());
            assertFalse(expire.isEmpty());
        } finally {
            tw.dispose();
        }
    }

    @Test
    public void expireReuseRace() {
        ConcurrentLinkedQueue<ThreadWorker> expire = new ConcurrentLinkedQueue<>();
        CompositeDisposable cd = new CompositeDisposable();

        ThreadWorker tw = new ThreadWorker(new RxThreadFactory("IoExpiryTest"));
        tw.dispose();

        for (int i = 0; i < TestHelper.RACE_DEFAULT_LOOPS; i++) {
            expire.add(tw);
            cd.add(tw);

            TestHelper.race(
                    () -> CachedWorkerPool.evictExpiredWorkers(expire, cd),
                    () -> expire.remove(tw)
            );
        }
    }

    /**
     * Verifies that ThreadWorker.expirationTime is declared volatile so that
     * updates made by one thread (e.g. release() refreshing expiration time)
     * are visible to the evictor thread reading it in evictExpiredWorkers().
     * Without volatile, the evictor may see a stale value (e.g. 0) and
     * incorrectly evict a worker that was just refreshed.
     */
    @Test
    public void expirationTimeMustBeVolatile() throws Exception {
        java.lang.reflect.Field f = ThreadWorker.class.getDeclaredField("expirationTime");
        assertTrue("expirationTime must be volatile for cross-thread visibility",
                Modifier.isVolatile(f.getModifiers()));
    }

    /**
     * Stress test: two threads concurrently setExpirationTime and getExpirationTime
     * on the same ThreadWorker. Without volatile, the reader may never see the
     * updated value due to lack of happens-before relationship.
     */
    @Test
    public void expirationTimeVisibilityStress() throws Exception {
        ThreadWorker tw = new ThreadWorker(new RxThreadFactory("VolTest"));
        try {
            // Reset to 0 so the reader starts with a stale value
            tw.setExpirationTime(0L);

            CountDownLatch writerReady = new CountDownLatch(1);
            CountDownLatch readerReady = new CountDownLatch(1);
            CountDownLatch writerDone = new CountDownLatch(1);
            AtomicBoolean sawUpdated = new AtomicBoolean(false);

            // Writer thread: sets expiration time to a large value
            Thread writer = new Thread(() -> {
                try {
                    readerReady.await();
                    // Spin a bit to make sure reader is spinning
                    Thread.sleep(1);
                    tw.setExpirationTime(System.nanoTime() + 1000_000_000L);
                    writerDone.countDown();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });

            // Reader thread: spins reading expirationTime until it sees the update
            Thread reader = new Thread(() -> {
                writerReady.countDown();
                try {
                    readerReady.await();
                    // Spin-read for a bounded time; with volatile we should see the update
                    long deadline = System.nanoTime() + 500_000_000L; // 500ms
                    while (System.nanoTime() < deadline) {
                        if (tw.getExpirationTime() != 0L) {
                            sawUpdated.set(true);
                            break;
                        }
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });

            writer.start();
            reader.start();

            reader.join(1000);
            writer.join(1000);

            // Without volatile, the reader thread may never see the updated value
            // because there's no happens-before relationship between the write
            // and the read. With volatile, the write is guaranteed to be visible.
            assertTrue("Reader should see updated expirationTime (volatile required for visibility)",
                    sawUpdated.get());
        } finally {
            tw.dispose();
        }
    }
}

