    @Test
    public void sampleTimedEmitLastWipLeakHangsOnComplete() throws Exception {
        // Regression test for wip leak in FlowableSampleTimed.SampleTimedEmitLast.run():
        // When the periodic timer fires twice before the first invocation decrements wip,
        // the second call increments wip to 3 (not 2) and skips the block entirely
        // without emitting or decrementing. This means wip grows permanently and
        // downstream.onComplete() will never be called when complete() is invoked.

        final java.util.concurrent.CountDownLatch blockOnNext = new java.util.concurrent.CountDownLatch(1);
        final java.util.concurrent.CountDownLatch firstRunEntered = new java.util.concurrent.CountDownLatch(1);

        @SuppressWarnings("unchecked")
        Subscriber<Integer> mockDownstream = mock(Subscriber.class);

        // Block onNext to simulate slow downstream - this makes the first run() stall
        doAnswer(invocation -> {
            firstRunEntered.countDown();
            blockOnNext.await(5, TimeUnit.SECONDS);
            return null;
        }).when(mockDownstream).onNext(any(Integer.class));
        doNothing().when(mockDownstream).onSubscribe(any(Subscription.class));

        // Directly construct the inner subscriber (same package access)
        FlowableSampleTimed.SampleTimedEmitLast<Integer> subscriber =
            new FlowableSampleTimed.SampleTimedEmitLast<>(mockDownstream, 1, TimeUnit.SECONDS,
                Schedulers.single(), null);

        // Set a value so emit() has something to send
        subscriber.set(42);

        // Set backpressure demand
        subscriber.request(Long.MAX_VALUE);

        // Call run() from thread 1 - it will increment wip 1->2 and enter the block,
        // then block on downstream.onNext in emit()
        Thread thread1 = new Thread(() -> subscriber.run());
        thread1.start();

        // Wait for the first run to enter the block
        firstRunEntered.await(5, TimeUnit.SECONDS);

        // Now call run() from thread 2 - this increments wip 2->3, != 2, skips block
        // WITHOUT decrementing! This is the bug.
        Thread thread2 = new Thread(() -> subscriber.run());
        thread2.start();

        // Wait for thread2 to finish (it returns quickly since it skips)
        thread2.join(5000);

        // Release the latch to let thread1 finish
        blockOnNext.countDown();
        thread1.join(5000);

        // Now call complete() - due to the bug, wip is > 1 (should be 1, but is 2 or more),
        // so wip.decrementAndGet() won't reach 0 and onComplete will never be called
        subscriber.complete();

        // This verify SHOULD pass (onComplete should be called)
        // but FAILS due to the wip leak bug
        verify(mockDownstream).onComplete();
    }

