package io.reactivex.rxjava4.internal.util;

import static org.junit.Assert.*;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

import org.junit.Test;

import io.reactivex.rxjava4.core.RxJavaTest;

public class VolatileSizeArrayListTest extends RxJavaTest {

    @Test
    public void normal() {
        List<Integer> list = new VolatileSizeArrayList<>();

        assertTrue(list.isEmpty());
        assertEquals(0, list.size());
        assertFalse(list.contains(1));
        assertFalse(list.remove((Integer)1));

        list = new VolatileSizeArrayList<>(16);
        assertTrue(list.add(1));
        assertTrue(list.addAll(Arrays.asList(3, 4, 7)));
        list.add(1, 2);
        assertTrue(list.addAll(4, Arrays.asList(5, 6)));

        assertTrue(list.contains(2));
        assertFalse(list.remove((Integer)10));

        assertEquals(Arrays.asList(1, 2, 3, 4, 5, 6, 7), list);
        assertFalse(list.isEmpty());
        assertEquals(7, list.size());

        Iterator<Integer> it = list.iterator();
        for (int i = 1; i < 8; i++) {
            assertEquals(i, it.next().intValue());
        }

        assertArrayEquals(new Object[] { 1, 2, 3, 4, 5, 6, 7 }, list.toArray());
        assertArrayEquals(new Integer[] { 1, 2, 3, 4, 5, 6, 7 }, list.toArray(new Integer[7]));

        assertTrue(list.containsAll(Arrays.asList(2, 4, 6)));
        assertFalse(list.containsAll(Arrays.asList(2, 4, 6, 10)));

        assertFalse(list.removeAll(Arrays.asList(10, 11, 12)));

        assertFalse(list.retainAll(Arrays.asList(1, 2, 3, 4, 5, 6, 7)));

        assertEquals(7, list.size());

        for (int i = 1; i < 8; i++) {
            assertEquals(i, list.get(i - 1).intValue());
        }

        for (int i = 1; i < 8; i++) {
            assertEquals(i, list.set(i - 1, i).intValue());
        }

        assertEquals(2, list.indexOf(3));

        assertEquals(5, list.lastIndexOf(6));

        ListIterator<Integer> lit = list.listIterator(7);
        for (int i = 7; i > 0; i--) {
            assertEquals(i, lit.previous().intValue());
        }

        assertEquals(Arrays.asList(3, 4, 5), list.subList(2, 5));

        VolatileSizeArrayList<Integer> list2 = new VolatileSizeArrayList<>();
        list2.addAll(Arrays.asList(1, 2, 3, 4, 5, 6));

        assertNotEquals(list2, list);
        assertNotEquals(list, list2);

        list2.add(7);
        assertEquals(list2, list);
        assertEquals(list, list2);

        List<Integer> list3 = new ArrayList<>();
        list3.addAll(Arrays.asList(1, 2, 3, 4, 5, 6));

        assertNotEquals(list3, list);
        assertNotEquals(list, list3);

        list3.add(7);
        assertEquals(list3, list);
        assertEquals(list, list3);

        assertEquals(list.hashCode(), list3.hashCode());
        assertEquals(list.toString(), list3.toString());

        list.remove(0);
        assertEquals(6, list.size());

        list.clear();
        assertEquals(0, list.size());
        assertTrue(list.isEmpty());
    }

    @Test
    public void setMemoryVisibility() throws InterruptedException {
        // Demonstrates that set() must call a volatile write (lazySet or set)
        // on the AtomicInteger's value to establish a happens-before edge.
        // Without it, element writes from set() may not be visible to other
        // threads even after they read the volatile size.
        //
        // CyclicBarrier synchronizes START of both threads, but NOT their
        // post-barrier actions. So writer's set() after barrier has no
        // happens-before edge to reader's read after barrier.
        VolatileSizeArrayList<Integer> list = new VolatileSizeArrayList<>(1);
        list.add(0); // size = 1, volatile write via add()'s lazySet

        AtomicBoolean staleSeen = new AtomicBoolean(false);
        CyclicBarrier barrier = new CyclicBarrier(2);

        Thread writer = new Thread(() -> {
            try {
                barrier.await(); // sync START with reader
            } catch (InterruptedException | BrokenBarrierException e) {
                Thread.currentThread().interrupt();
                return;
            }
            // After barrier: no happens-before edge to reader's post-barrier actions
            list.set(0, 42);
        });

        Thread reader = new Thread(() -> {
            try {
                barrier.await(); // sync START with writer
            } catch (InterruptedException | BrokenBarrierException e) {
                Thread.currentThread().interrupt();
                return;
            }
            // After barrier: read volatile size then element
            // Without volatile write in set(), element may be stale
            int size = list.size();
            if (size == 1) {
                int val = list.get(0);
                if (val != 42) {
                    staleSeen.set(true);
                }
            }
        });

        writer.start();
        reader.start();
        writer.join(5000);
        reader.join(5000);

        assertFalse("set() should establish happens-before via volatile write so element updates are visible", staleSeen.get());
    }
}

